// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract ArenaCoin is ERC20, Ownable {
    constructor(address initialOwner) ERC20("ArenaCoin", "ARENA") Ownable(initialOwner) {
        _mint(initialOwner, 1_000_000 * 10 ** decimals());
    }

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

contracts/ArenaFighterNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ArenaFighterNFT
 * @notice ERC721 contract for mintable fighter NFTs with rarity tiers.
 * 
 * SECURITY NOTE (HIGH-4 Mitigation):
 * Rarity determination uses block.timestamp and block.prevrandao (weak RNG).
 * Since only the contract owner can mint, rarity is deterministic but controlled 
 * by the owner/minter. For production randomness guarantees, integrate Chainlink VRF v2.5
 * before removing owner control or deploying to a multi-signer environment.
 */
contract ArenaFighterNFT is ERC721, Ownable {
    uint256 private _nextTokenId;

    enum Rarity { Common, Rare, Epic, Legendary }

    struct Fighter {
        uint256 strength;
        uint256 speed;
        uint256 intelligence;
        uint256 wins;
        uint256 losses;
        Rarity rarity;
    }

    mapping(uint256 => Fighter) public fighters;

    event FighterMinted(address indexed player, uint256 indexed tokenId, Rarity rarity);

    constructor(address initialOwner) ERC721("Arena Fighter", "AFIGHT") Ownable(initialOwner) {}

    function mintFighter(address player) external onlyOwner returns (uint256) {
        uint256 tokenId = _nextTokenId++;
        _safeMint(player, tokenId);

        uint256 seed = uint256(keccak256(abi.encodePacked(block.timestamp, block.prevrandao, player, tokenId)));

        Rarity rarity;
        uint256 rarityRoll = seed % 100;
        if (rarityRoll < 50) {
            rarity = Rarity.Common;
        } else if (rarityRoll < 80) {
            rarity = Rarity.Rare;
        } else if (rarityRoll < 95) {
            rarity = Rarity.Epic;
        } else {
            rarity = Rarity.Legendary;
        }

        uint256 baseBonus = uint256(rarity) * 10;

        fighters[tokenId] = Fighter({
            strength: 10 + (seed % 40) + baseBonus,
            speed: 10 + ((seed >> 8) % 40) + baseBonus,
            intelligence: 10 + ((seed >> 16) % 40) + baseBonus,
            wins: 0,
            losses: 0,
            rarity: rarity
        });

        emit FighterMinted(player, tokenId, rarity);
        return tokenId;
    }

    function getFighter(uint256 tokenId) external view returns (Fighter memory) {
        require(_ownerOf(tokenId) != address(0), "Fighter does not exist");
        return fighters[tokenId];
    }

    function totalSupply() external view returns (uint256) {
        return _nextTokenId;
    }
}

contracts/ArenaLeaderboard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

contract ArenaLeaderboard is Ownable {
    struct PlayerStats {
        uint256 totalWins;
        uint256 totalBattles;
        uint256 totalRewards;
    }

    struct SeasonStats {
        uint256 wins;
        uint256 battles;
        uint256 rewards;
    }

    struct Season {
        uint256 startTime;
        uint256 endTime;
        uint256 rewardPool;
        bool active;
    }

    // Global stats
    mapping(address => PlayerStats) public playerStats;
    address[] public registeredPlayers;
    mapping(address => bool) public isRegistered;

    // Seasonal stats
    mapping(uint256 => Season) public seasons;
    mapping(uint256 => mapping(address => SeasonStats)) public seasonStats;
    uint256 public currentSeasonId;

    address public battleContract;

    event StatsUpdated(address indexed player, uint256 wins, uint256 battles, uint256 rewards);
    event SeasonStarted(uint256 indexed seasonId, uint256 startTime, uint256 endTime);
    event SeasonEnded(uint256 indexed seasonId, address topWinner, uint256 topReward);

    modifier onlyBattle() {
        require(msg.sender == battleContract || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor(address initialOwner) Ownable(initialOwner) {}

    function setBattleContract(address _battleContract) external onlyOwner {
        battleContract = _battleContract;
    }

    function recordFight(address player, bool win, uint256 reward) external onlyBattle {
        // Register player if new
        if (!isRegistered[player]) {
            registeredPlayers.push(player);
            isRegistered[player] = true;
        }

        // Update global stats
        playerStats[player].totalBattles++;
        if (win) {
            playerStats[player].totalWins++;
            playerStats[player].totalRewards += reward;
        }

        // Update seasonal stats if season is active
        if (seasons[currentSeasonId].active) {
            seasonStats[currentSeasonId][player].battles++;
            if (win) {
                seasonStats[currentSeasonId][player].wins++;
                seasonStats[currentSeasonId][player].rewards += reward;
            }
        }

        emit StatsUpdated(
            player,
            playerStats[player].totalWins,
            playerStats[player].totalBattles,
            playerStats[player].totalRewards
        );
    }

    // Admin: Start a new season
    function startSeason(uint256 endTime, uint256 rewardPool) external onlyOwner {
        require(endTime > block.timestamp, "End time must be in future");

        uint256 seasonId = currentSeasonId + 1;
        seasons[seasonId] = Season({
            startTime: block.timestamp,
            endTime: endTime,
            rewardPool: rewardPool,
            active: true
        });

        currentSeasonId = seasonId;
        emit SeasonStarted(seasonId, block.timestamp, endTime);
    }

    // Admin: End season and emit event
    function endSeason() external onlyOwner {
        require(seasons[currentSeasonId].active, "No active season");

        uint256 seasonId = currentSeasonId;
        seasons[seasonId].active = false;

        // Find top winner this season (off-chain sorting recommended)
        address topWinner = address(0);
        uint256 topWins = 0;
        for (uint256 i = 0; i < registeredPlayers.length; i++) {
            if (seasonStats[seasonId][registeredPlayers[i]].wins > topWins) {
                topWins = seasonStats[seasonId][registeredPlayers[i]].wins;
                topWinner = registeredPlayers[i];
            }
        }

        emit SeasonEnded(seasonId, topWinner, topWins);
    }

    // MED-3: Get player stats for a specific season (off-chain sorted)
    function getSeasonStats(uint256 seasonId, address player) external view returns (SeasonStats memory) {
        return seasonStats[seasonId][player];
    }

    function getPlayerStats(address player) external view returns (PlayerStats memory) {
        return playerStats[player];
    }

    function totalPlayers() external view returns (uint256) {
        return registeredPlayers.length;
    }

    function getRegisteredPlayers() external view returns (address[] memory) {
        return registeredPlayers;
    }
}

